  function registerStudent(input){return mutate(state=>{const required=['username','password','confirmPassword','realName','phone'];const missing=required.find(key=>!String(input[key]||'').trim());if(missing)return fail('请完整填写注册信息',{field:missing});const username=String(input.username).trim();if(state.users.some(item=>item.username===username))return fail('用户名已存在',{field:'username'});if(input.password!==input.confirmPassword)return fail('两次输入的密码不一致',{field:'confirmPassword'});if(!/^1\d{10}$/.test(input.phone))return fail('请输入正确的11位手机号',{field:'phone'});const students=state.users.filter(item=>item.role==='student'),user={id:newId('S',students),username,password:input.password,role:'student',role_type:'STUDENT',name:String(input.realName).trim(),phone:input.phone};state.users.push(user);return ok('注册成功，请登录',clone(user));});}
