      const id='WO'+new Date().getFullYear()+String(Date.now()).slice(-8),createdAt=now(),student=currentUser(state); const order={id,studentId:student.id,location:{campus:input.campus,area:input.area,building:input.building,room:input.room,detail:input.detail||''},faultType:input.faultType,title:input.title||input.description.slice(0,16),description:input.description,contact:input.contact,phone:input.phone,status:'待接单',assigneeId:'W001',createdAt,acceptDeadline:'今日 17:30',completeDeadline:null,flags:duplicate?['疑似重复']:[],images:input.images||[],processes:[],materials:[],transitions:[{type:'学生提交工单',from:null,to:'待派单',actor:student.name,reason:'填写并提交报修信息',assigneeFrom:null,assigneeTo:null,time:createdAt},{type:'系统派单',from:'待派单',to:'待接单',actor:'系统',reason:'自动派单给张师傅',assigneeFrom:null,assigneeTo:'W001',time:createdAt}],reworkCount:0,rating:null}; state.orders.unshift(order); return ok('报修提交成功',clone(order));
