  function addProcess(id,input){return mutate(state=>{const order=state.orders.find(o=>o.id===id);if(!ownsOrder(state,order))return fail('只能处理分派给本人的工单');if(!['维修中','返工中'].includes(order.status))return fail('当前状态不能添加维修记录');if(!input.content?.trim())return fail('请填写处理内容');const actor=currentUser(state).name;order.processes.push({time:now(),worker:actor,content:input.content,images:input.images||[]});addTransition(order,'维修处理记录',order.status,order.status,actor,input.content,order.assigneeId,order.assigneeId);return ok('维修记录已添加');});}
