  function requestTransfer(id,input){return mutate(state=>{const order=state.orders.find(o=>o.id===id);if(!order||!['维修中','返工中','已中断'].includes(order.status))return fail('当前状态不能申请转派');if(!input.reason?.trim())return fail('请选择转派原因');const req={id:newId('TR',state.transferRequests),orderId:id,workerId:order.assigneeId,reason:input.reason,detail:input.detail||'',status:'待审批',createdAt:now()};state.transferRequests.unshift(req);addTransition(order,'维修人员申请转派',order.status,order.status,currentUser(state).name,input.reason,order.assigneeId,order.assigneeId);return ok('转派申请已提交',clone(req));});}
