  function manualDispatch(id,workerId){return mutate(state=>{const order=state.orders.find(o=>o.id===id);const worker=state.workers.find(w=>w.id===workerId);if(!order||!worker)return fail('工单或维修人员不存在');if(worker.status!=='正常'||!worker.skills.includes(order.faultType)||!worker.areas.includes(order.location.campus))return fail('该人员不满足技能、区域或可用状态要求');const old=order.assigneeId;order.assigneeId=worker.id;order.status='待接单';order.acceptDeadline='派单后30分钟有效工作时间';order.flags=order.flags.filter(f=>!['派单失败','管理员待办'].includes(f));addTransition(order,'人工派单','待派单','待接单','管理员','人工选择维修人员',old,worker.id);return ok('人工派单成功');});}
